import{_ as e,C as s,o as d,c as n,j as i,E as r,a as l,a2 as t}from"./chunks/framework.C21TwvGF.js";const b=JSON.parse(`{"title":"5-hafta","description":"","frontmatter":{"title":"5-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (DevOps)","link":"/10-sinf-devops/"},"n":5,"bob":"III-bob · Kompyuter tarmoqlari","lessons":[{"g":13,"title":"Matn filtralari va muntazam ifodalar: grep, sed, awk va xargs amaliyoti","lead":"Server logi millionlab qator. Ko'z bilan o'qib bo'lmaydi, lekin grep, sed va awk bilan bir soniyada kerakli narsani topamiz.","link":"/10-sinf-devops/hafta-05/dars-1","slide":"/slaydlar/10-sinf-devops/hafta-05/dars-1.html","test":"/slaydlar/10-sinf-devops/hafta-05/dars-1-test.html"},{"g":14,"title":"Linux jarayonlari va rejalashtirish: cron, crontab, at va tizim monitoringi (htop, iotop)","lead":"Server har kecha o'zi zaxira oladi, uxlayotganingizda ham. Buni cron qiladi. Bugun vazifalarni vaqtga bog'lashni va tizim yuklamasini kuzatishni o'rganamiz.","link":"/10-sinf-devops/hafta-05/dars-2","slide":"/slaydlar/10-sinf-devops/hafta-05/dars-2.html","test":"/slaydlar/10-sinf-devops/hafta-05/dars-2-test.html"},{"g":15,"title":"Linux xavfsizligi va foydalanuvchilar: useradd, usermod, sudoers, SSH kalitlar bilan xavfsiz ulanish","lead":"Serverga uchta dasturchi kirishi kerak. Hamma bitta parol bilan kirsa, kim nima qilganini bilib bo'lmaydi. Bugun hisoblar, huquqlar va SSH kalitlarni o'rganamiz.","link":"/10-sinf-devops/hafta-05/dars-3","slide":"/slaydlar/10-sinf-devops/hafta-05/dars-3.html","test":"/slaydlar/10-sinf-devops/hafta-05/dars-3-test.html"}],"test":"/slaydlar/10-sinf-devops/hafta-05/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-devops/hafta-05/index.md","filePath":"10-sinf-devops/hafta-05/index.md"}`),c={name:"10-sinf-devops/hafta-05/index.md"},h={class:"blk"},g={id:"uyga-vazifa",tabindex:"-1"};function f(v,a,m,u,k,p){const o=s("Icon");return d(),n("div",null,[i("div",h,[i("h2",g,[r(o,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=t('<p>5-haftada matn bilan ishlash vositalari (<code>grep</code>, <code>sed</code>, <code>awk</code>, <code>xargs</code>), jarayonlar va rejalashtirish (<code>cron</code>, <code>at</code>, <code>htop</code>, <code>iotop</code>) hamda foydalanuvchilar va SSH kalitlar o&#39;rganildi. Quyidagi topshiriqlar shu ko&#39;nikmalarni mustahkamlaydi.</p><hr><h3 id="_13-dars-vazifasi-grep-sed-awk-va-xargs" tabindex="-1">13-dars vazifasi: grep, sed, awk va xargs <a class="header-anchor" href="#_13-dars-vazifasi-grep-sed-awk-va-xargs" aria-label="Permalink to &quot;13-dars vazifasi: grep, sed, awk va xargs&quot;">​</a></h3><ol><li><code>app.log</code> ga kamida 10 qator yozing (INFO, WARN, ERROR aralash).</li><li><code>grep -c</code> bilan har daraja sonini toping.</li><li><code>awk</code> bilan faqat ERROR qatorlaridagi foydalanuvchi nomlarini ajrating.</li><li><code>sed</code> bilan ERROR ni XATO ga almashtiring (natijani yangi faylga yo&#39;naltiring).</li><li><code>tahlil.sh</code> skriptiga hammasini yig&#39;ib, natijani daftaringizga yozing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h3 id="_14-dars-vazifasi-cron-at-va-monitoring" tabindex="-1">14-dars vazifasi: cron, at va monitoring <a class="header-anchor" href="#_14-dars-vazifasi-cron-at-va-monitoring" aria-label="Permalink to &quot;14-dars vazifasi: cron, at va monitoring&quot;">​</a></h3><ol><li><code>tekshir.sh</code> yozing: sana va bo&#39;sh disk joyini (<code>df -h /</code>) <code>~/tekshir.log</code> ga qo&#39;shib yozsin.</li><li>Skriptni <code>chmod +x</code> qiling va to&#39;liq yo&#39;l bilan har 5 daqiqada ishlaydigan crontab qatorini qo&#39;shing.</li><li><code>crontab -l</code> natijasini va <code>tekshir.log</code> ning bir nechta qatorini daftaringizga yozing, so&#39;ng vazifani o&#39;chiring.</li><li><code>at now + 3 minutes</code> bilan <code>salom.txt</code> yarating; <code>atq</code> ni tekshiring.</li><li><code>htop</code> va <code>iotop</code> ekranini tavsiflang: eng ko&#39;p CPU va disk ishlatgan 3 jarayon nomini yozing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h3 id="_15-dars-vazifasi-foydalanuvchilar-sudoers-va-ssh" tabindex="-1">15-dars vazifasi: Foydalanuvchilar, sudoers va SSH <a class="header-anchor" href="#_15-dars-vazifasi-foydalanuvchilar-sudoers-va-ssh" aria-label="Permalink to &quot;15-dars vazifasi: Foydalanuvchilar, sudoers va SSH&quot;">​</a></h3><ol><li>Virtual mashinada <code>dasturchi1</code> hisobini yarating (<code>useradd -m -s /bin/bash</code>) va parol bering.</li><li><code>dasturchi1</code> ni <code>sudo</code> va <code>docker</code> guruhlariga <code>-aG</code> bilan qo&#39;shing; <code>id</code> natijasini yozing.</li><li><code>ssh-keygen -t ed25519</code> bilan kalit yarating; ochiq va shaxsiy kalit fayllarini tavsiflang.</li><li><code>~/.ssh</code> va kalit fayllariga to&#39;g&#39;ri ruxsatlarni bering (<code>chmod 700</code>, <code>chmod 600</code>).</li><li><code>sshd_config</code> da xavfsizlik sozlamalari (parolni o&#39;chirish, root kirishini taqiqlash) ni sinfdagi namunaviy serverda ko&#39;rsating yoki daftarga yozing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr>',11))])])}const z=e(c,[["render",f]]);export{b as __pageData,z as default};
